{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The emergence and growth in antibiotic resistant bacteria is a critical public health problem exacerbated by the misuse of antibiotics. Children frequently succumb to illness and are often treated with antibiotic medicines which may be used improperly by the parent. There is limited evidence of the factors influencing parental decision-making about the use of antibiotics in low-resource contexts.",
      "reason": "The abstract background describes the current state of knowledge (AMR problem, parental antibiotic misuse) and explicitly identifies the evidence gap/uncertainty (limited evidence on parental decision-making in low-resource contexts)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "There is limited evidence of the factors influencing parental decision-making about the use of antibiotics in low-resource contexts. The aim of this systematic review was to understand and describe how parents living in rural and remote locations make choices about their children's antibiotic use.",
      "reason": "The need for the review is established by identifying the evidence gap, and the review aim is stated in direct response to that gap."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence contains no discussion of existing similar systematic reviews, nor any statement explaining the need for the current review relative to prior reviews or citing an earlier review being updated/replicated."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a descriptive/qualitative synthesis review of parental decision-making determinants, not a review of intervention effects, so no mechanism of action of an intervention needs describing."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a complex intervention or delivery context requiring a logic model; it synthesises observational/qualitative evidence on decision-making determinants."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Thus, the objective of this review was to systematically describe the decision-making process of rural parents regarding their use of antibiotics. We sought to address the following research question: What factors influence the decisions of parents with children living in rural and remote locations in their use of antibiotics?",
      "reason": "The Background section explicitly states the review objective and a clearly formulated research question addressing the review's aim."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "the objective of this review was to systematically describe the decision-making process of rural parents regarding their use of antibiotics",
      "reason": "This is a descriptive review of factors influencing parental decision-making, not a review of intervention effects, so planned comparisons in PICO form do not apply. PICOS was only mentioned as a framework for developing search terms (text_4), not for stating planned comparisons."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Studies were eligible if they provided data on the decision-making process of parents living in rural and remote locations in their use of antibiotics with their children (aged 0-18 years)... We considered quantitative and qualitative designs, mixed methods, observational, prospective, systematic reviews, crosssectional and longitudinal studies.",
      "reason": "Population (parents/caregivers of children 0-18 in rural/remote locations), setting, concept (decision-making factors), and eligible study designs are all explicitly specified, along with exclusions (urban/semi-urban settings, non-parent samples, other antimicrobials)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Worldwide studies available in English were included, and no restrictions were placed on the publication period. Both peerreviewed and grey literature were accepted.",
      "reason": "Report characteristics are specified: language (English only), no dissemination year restriction, and publication status (peer-reviewed and grey literature accepted)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_12",
      "quote": "Reports were excluded for the following three reasons using the full-text decision tree tool: (1) participant characteristics were not suitable (2) the study did not provide exclusive results for parents/caregivers, or antibiotics, or parents living in rural or remote areas (3) the study did not provide data on the decisionmaking process of rural parents",
      "reason": "The review's eligibility is not based on specific outcome measurement; no exclusion criterion distinguishes outcomes not measured from results not reported, so this conditional distinction does not apply."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Primary findings were categorised into groups for the synthesis: (1) the process of decision-making to use or not use antibiotics i.e., influences on antibiotic use (2) factors contributing to specific behaviours with antibiotics identified i.e., non-prescription use of antibiotics, non-adherence to antibiotic treatment, requests for antibiotic prescriptions.",
      "reason": "The synthesis groups are explicitly specified and correspond to the review objective of describing parental decision-making about children's antibiotic use."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "A pre-determined JBI score of 60% or above was decided by the review team, which is indicative of moderate to high-quality studies [22]... Inclusion of studies scoring low on JBI may jeopardise the validity of the review findings [23].",
      "reason": "A rationale is given for the quality-based inclusion threshold, but no rationale is provided for other notable restrictions such as the English-language limitation or exclusion of urban/semi-urban settings."
    }
  ],
  "confidence": 88
}

