{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The following pre-specified data was collected from each eligible study... author name; year of publication; country; study aim; study setting/context; participant information (caregiver and child characteristics); study design and methodology; key findings (principal outcomes and results relevant to the current research); and study limitations. The primary outcome of interest was: the drivers/determinants of parents' decisions towards the use of antibiotics with their children.",
      "reason": "The Data Extraction section lists and defines all data items collected, including participant characteristics, study design, outcomes, and funding-related context is not mentioned but variables are comprehensively listed."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "In one study, participants were described as 'parents/carers of young children' and the age range of the children was not specified [20]. However, we included this study based on the assumption that 'young children' was the same as pre-adolescents (primary school age and younger), given that parents were recruited through early childhood education services and playgroups.",
      "reason": "The authors explicitly describe an assumption made about unclear participant age information in one included study."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "We assessed the possibility of bias and the methodological quality of studies included in the next phase of the review, using the Joanna Briggs Institute (JBI) critical appraisal checklists.",
      "reason": "The JBI critical appraisal checklists are cited as the tool guiding quality assessment; however, no specific tool is cited for determining which data items to collect, only that items were 'similar to the information extracted in prior reviews [4]'. This is a partial citation of a guiding source rather than a formal data collection tool, so PRESENT is borderline but the reference to prior reviews and JBI scoring thresholds supports it."
    }
  ],
  "confidence": 82
}

